// Generated by scripts/fetch-bird-images.mjs
export const normalizeBirdName = (value = '') =>
  String(value)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[\u2018\u2019`]/g, "\'")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

